"""Shared code of the frozen contract folders (CR-09).

Each `tests/contracts/<component>.<Symbol>/` folder holds `schema.json` (JSON Schema, the subset
`schema_errors` checks), `samples/*.json` (one per contract case) and, for a Protocol or class,
`double.py` (a replay double serving its recording) or, for a boundary function, `fake.py` (the
provider's signature, serving its fixtures). The builders below turn a sample into its contract
type.

Doubles and fakes import this module as `contract_support`. From any test, load it once by path,
then load a folder's double or fake through it:

    spec = importlib.util.spec_from_file_location("contract_support", CONTRACTS / "support.py")
    support = importlib.util.module_from_spec(spec)
    sys.modules["contract_support"] = support
    spec.loader.exec_module(support)
    world = support.load("core.World", "double").double()
"""

from __future__ import annotations

import importlib.util
import json
import math
import sys
from datetime import datetime, timedelta
from pathlib import Path
from types import ModuleType
from typing import Any

import numpy as np

from rllab.baselines import BaselineMeans
from rllab.core import (
    ActionError,
    ActionSpace,
    Box,
    Discrete,
    Drawable,
    DrawState,
    Episode,
    EpisodeResult,
    Frame,
    MeasureSpec,
    Output,
    Step,
    TeamSpec,
    WorldSpec,
)
from rllab.evaluate import Comparison, Summary, Verdict
from rllab.methods import MethodConfig, Transition
from rllab.runlog import Checkpoint, EvalPoint, Failure, Progress, RunRecord
from rllab.train import CheckResult, RunConfig

HERE = Path(__file__).resolve().parent


# ------------------------------------------------------------------------------ files
def read(folder: str, name: str) -> Any:
    """One sample of a contract folder, parsed."""
    return json.loads((HERE / folder / "samples" / f"{name}.json").read_text(encoding="utf-8"))


def sample_names(folder: str) -> list[str]:
    return sorted(p.stem for p in (HERE / folder / "samples").glob("*.json"))


def load(folder: str, kind: str) -> ModuleType:
    """A folder's `double.py` or `fake.py`, imported once."""
    name = f"contract_{folder.replace('.', '_')}_{kind}"
    if name not in sys.modules:
        spec = importlib.util.spec_from_file_location(name, HERE / folder / f"{kind}.py")
        assert spec is not None
        assert spec.loader is not None
        module = importlib.util.module_from_spec(spec)
        sys.modules[name] = module
        spec.loader.exec_module(module)
    return sys.modules[name]


# ------------------------------------------------------------------- schema checking
TYPES: dict[str, tuple[type, ...]] = {
    "object": (dict,),
    "array": (list,),
    "string": (str,),
    "number": (int, float),
    "integer": (int,),
    "boolean": (bool,),
    "null": (type(None),),
}


def schema_errors(instance: Any, folder: str) -> list[str]:
    """Where `instance` breaks the folder's `schema.json`; empty when it validates."""
    path = HERE / folder / "schema.json"
    return _check(instance, _schema(path), path, "$")


def _schema(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def _is_type(value: Any, names: str | list[str]) -> bool:
    for name in [names] if isinstance(names, str) else names:
        bool_ok = name == "boolean" or not isinstance(value, bool)
        if isinstance(value, TYPES[name]) and bool_ok:
            return True
    return False


def _check(value: Any, schema: dict[str, Any], base: Path, where: str) -> list[str]:
    if "$ref" in schema:
        target = (base.parent / schema["$ref"]).resolve()
        return _check(value, _schema(target), target, where)
    if "anyOf" in schema and all(_check(value, s, base, where) for s in schema["anyOf"]):
        return [f"{where}: matches none of anyOf"]
    if "const" in schema and value != schema["const"]:
        return [f"{where}: {value!r} is not {schema['const']!r}"]
    if "enum" in schema and value not in schema["enum"]:
        return [f"{where}: {value!r} not in {schema['enum']}"]
    if "type" in schema and not _is_type(value, schema["type"]):
        return [f"{where}: {value!r} is not of type {schema['type']}"]
    if isinstance(value, dict):
        return _check_object(value, schema, base, where)
    if isinstance(value, list):
        return _check_array(value, schema, base, where)
    return _check_number(value, schema, where)


def _check_object(value: dict[str, Any], schema: dict[str, Any], base: Path, where: str) -> list[str]:
    errors = [f"{where}: missing {key!r}" for key in schema.get("required", []) if key not in value]
    props = schema.get("properties", {})
    extra = schema.get("additionalProperties", True)
    for key, item in value.items():
        if key in props:
            errors += _check(item, props[key], base, f"{where}.{key}")
        elif extra is False:
            errors.append(f"{where}: unexpected {key!r}")
        elif isinstance(extra, dict):
            errors += _check(item, extra, base, f"{where}.{key}")
    return errors


def _check_array(value: list[Any], schema: dict[str, Any], base: Path, where: str) -> list[str]:
    errors = []
    if len(value) < schema.get("minItems", 0):
        errors.append(f"{where}: fewer than {schema['minItems']} items")
    if len(value) > schema.get("maxItems", math.inf):
        errors.append(f"{where}: more than {schema['maxItems']} items")
    prefix = schema.get("prefixItems", [])
    for i, item in enumerate(value):
        sub = prefix[i] if i < len(prefix) else schema.get("items")
        if sub is not None:
            errors += _check(item, sub, base, f"{where}[{i}]")
    return errors


def _check_number(value: Any, schema: dict[str, Any], where: str) -> list[str]:
    if not _is_type(value, "number"):
        return []
    errors = []
    if "minimum" in schema and value < schema["minimum"]:
        errors.append(f"{where}: {value} < {schema['minimum']}")
    if "maximum" in schema and value > schema["maximum"]:
        errors.append(f"{where}: {value} > {schema['maximum']}")
    return errors


# ------------------------------------------------------------------- sample -> type
def array(rows: Any) -> np.ndarray:
    """Observations, rewards and float actions as float32; ints and bools keep their kind."""
    values = np.asarray(rows)
    return values.astype(np.float32) if values.dtype.kind == "f" else values


def action_space(d: dict[str, Any]) -> ActionSpace:
    if d["kind"] == "discrete":
        return Discrete(d["n"])
    return Box(d["dims"], d["low"], d["high"])


def team_spec(d: dict[str, Any]) -> TeamSpec:
    return TeamSpec(d["name"], tuple(d["agents"]), d["score_name"], d["direction"])


def world_spec(d: dict[str, Any]) -> WorldSpec:
    return WorldSpec(
        world=d["world"],
        variant=d["variant"],
        agents=tuple(d["agents"]),
        teams=tuple(team_spec(t) for t in d["teams"]),
        obs_len=d["obs_len"],
        action=action_space(d["action"]),
        max_steps=d["max_steps"],
        measures=tuple(MeasureSpec(**m) for m in d["measures"]),
        sight=d["sight"],
    )


def step(d: dict[str, Any]) -> Step:
    return Step(
        obs=np.asarray(d["obs"], dtype=np.float32),
        rewards=np.asarray(d["rewards"], dtype=np.float32),
        active=np.asarray(d["active"], dtype=bool),
        done=d["done"],
        truncated=d["truncated"],
    )


def episode_result(d: dict[str, Any]) -> EpisodeResult:
    return EpisodeResult(**d)


def draw_state(d: dict[str, Any]) -> DrawState:
    return DrawState(d["width"], d["height"], tuple(Drawable(**o) for o in d["objects"]))


def frame(d: dict[str, Any]) -> Frame:
    rewards = np.asarray(d["rewards"], dtype=np.float32)
    return Frame(d["step"], draw_state(d["draw"]), d["scores"], rewards)


def episode(d: dict[str, Any]) -> Episode:
    frames = None if d["frames"] is None else tuple(frame(f) for f in d["frames"])
    return Episode(episode_result(d["result"]), frames, d["hit_step_limit"])


def output(d: dict[str, Any]) -> Output:
    return Output(Path(d["path"]), d["kind"], tuple(d["made_from"]))


def method_config(d: dict[str, Any]) -> MethodConfig:
    return MethodConfig(d["method"], d["settings"])


def run_config(d: dict[str, Any]) -> RunConfig:
    return RunConfig(
        name=d["name"],
        world=d["world"],
        variant=d["variant"],
        methods={team: method_config(m) for team, m in d["methods"].items()},
        seed=d["seed"],
        budget=d["budget"],
        check_settings=d["check_settings"],
        device=d.get("device", "cpu"),
    )


def check_result(d: dict[str, Any]) -> CheckResult:
    return CheckResult(**d)


def run_record(d: dict[str, Any]) -> RunRecord:
    failure = d["failure"]
    return RunRecord(
        config=run_config(d["config"]),
        spec=world_spec(d["spec"]),
        started=datetime.fromisoformat(d["started"]),
        ended=None if d["ended"] is None else datetime.fromisoformat(d["ended"]),
        status=d["status"],
        failure=None
        if failure is None
        else Failure(failure["step"], failure["value"], Path(failure["checkpoint"])),
        path=Path(d["path"]),
    )


def eval_point(d: dict[str, Any]) -> EvalPoint:
    return EvalPoint(**d)


def checkpoint(d: dict[str, Any]) -> Checkpoint:
    return Checkpoint(
        run=d["run"],
        pct=d["pct"],
        step=d["step"],
        spec=world_spec(d["spec"]),
        methods={team: method_config(m) for team, m in d["methods"].items()},
        state=d["state"],
        path=Path(d["path"]),
    )


def progress(d: dict[str, Any]) -> Progress:
    latest = None if d["latest"] is None else eval_point(d["latest"])
    elapsed = timedelta(seconds=d["elapsed_seconds"])
    return Progress(d["step"], d["budget"], latest, elapsed, d["status"])


def baseline_means(d: dict[str, Any]) -> BaselineMeans:
    return BaselineMeans(**d)


def comparison(d: dict[str, Any]) -> Comparison:
    return Comparison(**d)


def summary(d: dict[str, Any]) -> Summary:
    v = d["verdict"]
    return Summary(
        world=d["world"],
        variant=d["variant"],
        team=d["team"],
        runs=tuple(d["runs"]),
        learned_mean=d["learned_mean"],
        learned_range=(d["learned_range"][0], d["learned_range"][1]),
        run_means=d["run_means"],
        random_mean=d["random_mean"],
        rule_mean=d["rule_mean"],
        comparisons=tuple(comparison(c) for c in d["comparisons"]),
        verdict=Verdict(v["beats_baselines"], tuple(v["failing_runs"]), v["runs_needed"]),
        collapse=d["collapse"],
    )


def transition(d: dict[str, Any]) -> Transition:
    return Transition(
        obs=np.asarray(d["obs"], dtype=np.float32),
        actions=array(d["actions"]),
        rewards=np.asarray(d["rewards"], dtype=np.float32),
        next_obs=np.asarray(d["next_obs"], dtype=np.float32),
        done=d["done"],
        truncated=d["truncated"],
        active=np.asarray(d["active"], dtype=bool),
    )


# ------------------------------------------------------------------- shared double logic
def check_actions(spec: WorldSpec, actions: np.ndarray) -> None:
    """`ActionError` naming the first agent whose action is outside `spec.action`."""
    space = spec.action
    for agent, row in zip(spec.agents, actions, strict=True):
        values = np.atleast_1d(row)
        if isinstance(space, Discrete):
            ok = values.size == 1 and float(values[0]).is_integer() and 0 <= values[0] < space.n
        else:
            ok = values.size == space.dims and bool(np.all((values >= space.low) & (values <= space.high)))
        if not ok:
            raise ActionError(agent, row.tolist())

