def check_actions(spec: WorldSpec, actions: np.ndarray) -> None:
    """`ActionError` naming the first agent whose action is outside `spec.action`."""
    space = spec.action
    for agent, row in zip(spec.agents, actions, strict=True):
        values = np.atleast_1d(row)
        if isinstance(space, Discrete):
            ok = values.size == 1 and float(values[0]).is_integer() and 0 <= values[0] < space.n
